#pragma once
inline unsigned splitPrototype(const std::vector<one::Fixture>& fs,const std::vector<one::FV>& dc){unsigned bad=0,gateBad=0;std::vector<std::map<unsigned,std::vector<uint32_t>>> anchor(24);
 for(bool tap:{false,true}){DiagnosticGraph g(tap?"split_tap":"split_native");auto x=g.tensor("dc",QNN_TENSOR_TYPE_APP_WRITE,{1,1,32,64});auto a=g.tensor("h0",tap?QNN_TENSOR_TYPE_APP_READ:QNN_TENSOR_TYPE_NATIVE,{1,1,32,32}),b=g.tensor("h1",tap?QNN_TENSOR_TYPE_APP_READ:QNN_TENSOR_TYPE_NATIVE,{1,1,32,32}),r=g.tensor("receipt",QNN_TENSOR_TYPE_APP_READ,{1,1,1,4104},QNN_DATATYPE_INT_32);g.node("split","HeadSplit","HexaFp32",{x},{a,b,r});
  auto ga=g.tensor("gate0",QNN_TENSOR_TYPE_APP_WRITE,{1,1,32,1}),gb=g.tensor("gate1",QNN_TENSOR_TYPE_APP_WRITE,{1,1,32,1}),ya=g.tensor("gated0",QNN_TENSOR_TYPE_APP_READ,{1,1,32,32}),yb=g.tensor("gated1",QNN_TENSOR_TYPE_APP_READ,{1,1,32,32});g.node("gate0_multiply",QNN_OP_ELEMENT_WISE_MULTIPLY,"qti.aisw",{a,ga},{ya});g.node("gate1_multiply",QNN_OP_ELEMENT_WISE_MULTIPLY,"qti.aisw",{b,gb},{yb});g.finalize();unsigned last=0;
  for(unsigned i=0;i<24;++i){auto o=g.run({{x,dc[i]},{ga,fs[i].v.at("h0_gate")},{gb,fs[i].v.at("h1_gate")}});auto& receipt=o[r];if(receipt[0]!=0x48383109u||receipt[1]<=last||receipt[2]!=2048||receipt[3]!=2||receipt[5]!=81||receipt[7]){std::puts("HEAD_SPLIT_RECEIPT_FAIL");std::exit(3);}last=receipt[1];for(unsigned j=0;j<2048;++j)if(receipt[8+j]!=word(dc[i][j])){std::puts("HEAD_SPLIT_INPUT_WORD_FAIL");std::exit(3);}
   for(unsigned head=0;head<2;++head){auto ref=one::split(one::d(dc[i]),head);auto pos=2056+head*1024;one::FV actual;for(unsigned j=0;j<1024;++j){if(receipt[pos+j]!=word(float(ref[j]))){std::puts("HEAD_SPLIT_OUTPUT_WORD_FAIL");std::exit(3);}actual.push_back(from(receipt[pos+j]));if(tap&&o[head?b:a][j]!=receipt[pos+j]){std::puts("HEAD_SPLIT_TAP_FAIL");std::exit(3);}}
    bad+=metric(tap?"splitTap":"splitNative",i,"h"+std::to_string(head)+"_selected",ref,ref,actual,.002);auto key="h"+std::to_string(head)+"_gate";auto expected=one::mul(ref,one::d(fs[i].v.at(key))),fp=one::mul(ref,one::d(fs[i].v.at(key)),true);auto output=decode(o[head?yb:ya]);gateBad+=metric(tap?"nextGateTap":"nextGateNative",i,"h"+std::to_string(head)+"_dc",expected,fp,output,.01);auto half=expected;for(auto& v:half)v=mmfixture::ln::halfLattice(v);std::printf("splitfrontier,%u,%u,tap=%u,word_mismatch=0,gate_half_output_model_abs=%.12g\n",head,i,tap,mmfixture::ln::errors(half,output).absolute);
   }if(!tap)anchor[i]={{0,o[ya]},{1,o[yb]}};else if(anchor[i][0]!=o[ya]||anchor[i][1]!=o[yb]){std::puts("HEAD_SPLIT_GATE_OBSERVER_FAIL");std::exit(3);}
  }
 }std::printf("prototype_summary,custom_split_failures=%u,next_gate_failures=%u,new_custom_operation_types=1\n",bad,gateBad);return bad;
}
inline unsigned producers(const std::vector<one::Fixture>& fs){OneGraph graph("producedSegmentTap",true,false,false,true);unsigned producerBad=0,localBad=0;
 for(auto& z:fs){auto o=graph.g.run(graph.inputs(z));auto actual=graph.audit(z,o);for(auto field:{"x","dy","context"}){std::string n=field;auto expected=one::d(z.v.at(n));producerBad+=metric("upstream",z.index,"producer_"+n,expected,expected,actual.at("up_"+n),n=="dy"?.01:.002);}
  for(auto field:{"q","k","v"}){std::string n=field;auto expected=one::mm(one::d(z.v.at("ln1")),one::d(z.v.at("w"+n)),32,64,64),fp=one::mm(one::d(z.v.at("ln1")),one::d(z.v.at("w"+n)),32,64,64,false,false,true);producerBad+=metric("upstream",z.index,"projection_"+n,expected,fp,actual.at("up_"+n),.002);}
  auto received=z;received.v["x"]=actual.at("up_x");received.v["dy"]=actual.at("up_dy");received.v["context"]=actual.at("up_context");auto ref=one::reference(received),fp=one::reference(received,true);
  for(auto field:{"dc","dw","y","xhat","inverse","dx","dg","db","residual"})localBad+=metric("producerLocalCustom",z.index,field,ref.at(field),fp.at(field),actual.at(field),limit(field));
 }std::printf("producer_summary,cases=24,upstream_failures=%u,local_custom_failures=%u,reference_fed_vs_produced_separate=1\n",producerBad,localBad);return localBad;
}
